head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.gDisclsStatCd_30 = '30'; // 승인
scwin.vPageMoveYn = 'Y';
scwin.gListProcsLogYn = 'Y';
scwin.vPROCS_STAT_NM = '';
scwin.vPROCS_DDTM = '';
scwin.vBLOCK_YN = '';
scwin.gAcptNo = $c.frame.path("../frame_head").scwin.gAcptNo;
scwin.gDisclsAcptTpCd = $c.frame.path("../frame_head").scwin.gDisclsAcptTpCd; // 공시접수유형
scwin.gProcsStatCd = $c.frame.path("../frame_head").scwin.gProcsStatCd;
scwin.gDutyYn = js_duty;
scwin.gDutyChrg = js_duty_chrg; // 세션정보
scwin.gEmpNo = js_emp_no; // 세션정보
scwin.gJobTitle = js_jobtitl; // 팀장  : 09,  부서장: 40,  팀원: 03

scwin.gProcYn;
scwin.gPublYn;
scwin.gExtrcYn;
scwin.gApprovYn;
scwin.gListFormYn;
scwin.gDisclsStatCd;

// var gAcptApplTpCd="";

scwin.vIsurCd;
scwin.vComAbbrv;
scwin.vSecuGrpId;
scwin.vMainFormCd;
scwin.vMktTpCd;
scwin.vListBzTpCd;
scwin.vUrl;
scwin.vWinTitle;
scwin.vPROCS_STAT_CD;
scwin.gTrdHaltMsg = $c.frame.path("../frame_head").scwin.gTrdHaltMsg;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.libRoundPanel.PanelToGroupBox(panel_12); // 패널라운드 처리
        // 로그인 사용자정보로 공시처리가능여부 체크

        // 유가 상장신청서 서식 처리절차가 098이 있으면 체크  20150403
        await scwin.listingProcsFlag();
        await scwin.getProcButtonYN();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF10105.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name img_close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_close_onclick = function() {
    try {
        $c.frame.path("../").fn_CloseWin();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF10105.img_close_onclick" });
    }
};

/**
 * @method
 * @name dts_btnshow_OnLoadCompleted
 * @description dts_btnshow 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_btnshow_OnLoadCompleted = async function(rowcount) {
    try {
        await scwin.showProcButton(dts_btnshow.getCellData(1, "DUTY_PROC_YN"), dts_btnshow.getCellData(1, "GRNL_PROC_YN"), dts_btnshow.getCellData(1, "CLOSE_YN"));
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF10105.dts_btnshow_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_btnshow_OnLoadError
 * @description dts_btnshow 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_btnshow_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_btnshow);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF10105.dts_btnshow_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_ListingProcsFlag_OnLoadError
 * @description dts_ListingProcsFlag 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_ListingProcsFlag_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_ListingProcsFlag);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF10105.dts_ListingProcsFlag_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_ListingProcsFlag_OnLoadCompleted
 * @description dts_ListingProcsFlag 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_ListingProcsFlag_OnLoadCompleted = function(rowcount) {
    try {
        scwin.gProcYn = dts_ListingProcsFlag.getCellData(1, "PROC_YN");
        scwin.gPublYn = dts_ListingProcsFlag.getCellData(1, "PUBL_YN");
        scwin.gExtrcYn = dts_ListingProcsFlag.getCellData(1, "EXTRC_YN");
        // 유가 상장신청서 서식 처리절차가 098이 있으면 체크  20150403
        scwin.gApprovYn = dts_ListingProcsFlag.getCellData(1, "APPROV_YN");
        scwin.gListFormYn = dts_ListingProcsFlag.getCellData(1, "LIST_FORM_YN");
        scwin.vIsurCd = dts_ListingProcsFlag.getCellData(1, "ISUR_CD");
        scwin.vComAbbrv = dts_ListingProcsFlag.getCellData(1, "COM_ABBRV");
        scwin.vSecuGrpId = dts_ListingProcsFlag.getCellData(1, "SECUGRP_ID");
        scwin.vMainFormCd = dts_ListingProcsFlag.getCellData(1, "FORM_CD");
        scwin.vMktTpCd = dts_ListingProcsFlag.getCellData(1, "LD_MKT_TP_CD");

        // alert('[gProcYn]' +gProcYn +'[gPublYn]'+gPublYn+'[gExtrcYn]'+gExtrcYn);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF10105.dts_ListingProcsFlag_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name trs_AcptList_OnSuccess
 * @description Acpt List On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_AcptList_OnSuccess = async function() {
    try {
        await $c.win.alert("성공적으로 검토처리 되었습니다.");
        scwin.closeParentReload();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF10105.trs_AcptList_OnSuccess" });
    }
};

/**
 * @method
 * @name trs_AcptList_OnFail
 * @description Acpt List On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_AcptList_OnFail = async function() {
    try {
        await $c.win.alert('trs_AcptList.OnFail() :' + trs_AcptList.ErrorMsg);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF10105.trs_AcptList_OnFail" });
    }
};

/**
 * @method
 * @name trs_AcptProcs_OnSuccess
 * @description Acpt Procs On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_AcptProcs_OnSuccess = async function() {
    try {
        let gMoveYn = 'N';

        // 20150807 SrM-000114761 예상상장수수료 삭제
        // fn_ListFeeCos();

        if (scwin.vPageMoveYn === 'Y' && (scwin.gDisclsAcptTpCd === 'F' || scwin.gDisclsAcptTpCd === 'M')) {
            // 상장신청서이고, 최초(F)나 정정(M) 처리화면으로 이동
            if (scwin.gApprovYn === 'Y') {
                gMoveYn = 'N'; // 유가 공시부는 팀장 승인이 있기 때문에 화면 이동하지 않음
                await $c.win.alert("성공적으로 처리 되었습니다.");
            } else {
                gMoveYn = 'Y';
                await $c.win.alert("성공적으로 처리 되었습니다. 업무처리화면으로 이동합니다.");
            }
        } else {
            await $c.win.alert("성공적으로 처리 되었습니다.");
        }

        // var pvd = fn_GetParentProvider();
        // pvd.fn_list_sync();
        scwin.closeParentReload();
        if (gMoveYn === 'Y') {
            await scwin.moveBizProcPage();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF10105.trs_AcptProcs_OnSuccess" });
    }
};

/**
 * @method
 * @name trs_AcptProcs_OnFail
 * @description Acpt Procs On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_AcptProcs_OnFail = async function() {
    try {
        await $c.win.alert('trs_AcptProcs.OnFail() :' + trs_AcptProcs.ErrorMsg);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF10105.trs_AcptProcs_OnFail" });
    }
};

/**
