        let winTitle = "유보처리";
        await $c.frame.CreateDialogFrame("gform", url, winTitle, 100, -500, 800, 370, "window");
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF10105.img_reserve_onclick" });
    }
};

