 */
scwin.img_print_onclick = function() {
    try {
        // fn_PrintFormCall();
        $c.frame.path("../frame_head").fn_PrintOpen();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF10105.img_print_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name listingProcsFlag
 * @description 상장문서 처리절차가져오기
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listingProcsFlag = async function() {
    const sbmOptions = {
        id : "sbm_dts_ListingProcsFlag",
        action : "/Viewer.do",
        ref : "",
        target : "dts_ListingProcsFlag=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

