        target : "dts_btnshow=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name dsclAcpt
 * @description 유가공시부 접수처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dsclAcpt = async function() {
    const sbmOptions = {
        id : "sbm_dts_AcptList",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "dts_AcptList=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    let vTrnsmtp = '1'; // 1=전송(일반) ,  2=비전송(HTS제외 전송) , 3=비공개(웹)

    dts_AcptList.insertRow();
    dts_AcptList.setCellData(1, "ACPT_NO", scwin.gAcptNo);
    dts_AcptList.setCellData(1, "TRNSM_TP_CD", vTrnsmtp);
    dts_AcptList.setCellData(1, "EMP_NO", scwin.gEmpNo);
    dts_AcptList.setCellData(1, "NXTDD_TDD_TP", "2");
    dts_AcptList.setCellData(1, "DISCLS_DUTY_TP_CD", js_duty_tp_cd);
    let vAnswer = confirm('검토처리 하시겠습니까?');
    if (vAnswer === true) {
        if (await scwin.checkProcsSate(scwin.gAcptNo) === false) {
            scwin.closeParentReload();
            return false;
        } else {
            trs_AcptList.KeyName = "toinb_dataid4";
            const sbmOptions = {
                id : "sbm_trs_AcptList",
                action : "/DisclosureStudy.do",
                ref : "dts_AcptList",
                target : "trs_AcptList=body.content",
                isProcessMsg : false
            };

            const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
            // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
        }
    }
};

/**
 * @method
 * @name dsclStudy
 * @description mktTP : 1:유가, 2:코스닥&코넥스 검토처리하기
 * @param {*} mktTP mktTP
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dsclStudy = async function(mktTP) {
    // 전송구분 셋팅

    if (scwin.gAcptNo === '') {
        await $c.win.alert("접수정보를 다시 읽어와야 하므로 공시뷰어를 닫으신후 다시 열어 주세요.");
        return false;
    }
    /*
    if (gListFormYn == 'Y') {
    	gDisclsStatCd = gDisclsStatCd_30;
    	gListProcsLogYn = 'Y';
    } else {
    	if (gPublYn == 'N') {
    		gDisclsStatCd = gDisclsStatCd_30;
    	} else {
    		gDisclsStatCd = gDisclsStatCd_00;
    	}
    }

    if (gListFormYn == 'N' && gPublYn == 'Y') {
    	gAcptApplTpCd = 'D'; //접수신청구분코드 (상장신청에서 공시접수로 변경한다. )
    }
     */

    // 유가가 아닌 경우에만 처리여부를 확인한다.
    // 유가는 검토, 승인 단계가 있지만 코&넥은 없음.  00이 아닌경우 튕겨 내도록했기에 검토,승인이 없는 코&넥만 적용.
    if (mktTP === 2) {
        if (await scwin.checkProcsSateKOSDAQ(scwin.gAcptNo) === false) {
            scwin.closeParentReload();
            return false;
        }
    }
    scwin.gDisclsStatCd = scwin.gDisclsStatCd_30; // 신고서식 모두 공시검토에서 처리하여 '30'으로 셋팅

    let vAnswer;
    if (scwin.gApprovYn === 'Y') {
        vAnswer = confirm('승인처리 하시겠습니까?');
    } else {
        vAnswer = confirm('접수처리 하시겠습니까?');
    }
    if (vAnswer === true) {
        scwin.setParam();
        let vBzProcsNo = "";
        if (scwin.gListProcsLogYn === 'Y') {
            vBzProcsNo = await $c.stf.getNewBzProcNo(dts_BzProcsNo);
            if (vBzProcsNo.length !== 14) {
                await $c.win.alert($c.stf.getMessageParam("MSG-0010", ""));
                return;
            }
        }

        /*
        alert("[vIsurCd(회사코드)]:"+vIsurCd+
        		"\n[gListFormYn(상장신청서 여부)]:"+gListFormYn+
        		"\n[gPublYn(공시처리여부)]:"+gProcYn+
        		"\n[gPublYn(배포여부)]:"+gPublYn+
        		"\n[gPublYn(추출여부)]:"+gExtrcYn+
        		"\n[gAcptApplTpCd(접수신청구분)]:"+gAcptApplTpCd
        		);
         */ //
        await scwin.setHeader();
        let vTrnsmtp = '1'; // 1=전송(일반) ,  2=비전송(HTS제외 전송) , 3=비공개(웹)
        // var vTrnsmtp = getObjectValue(rdo_trnsmtp);
        // alert(vTrnsmtp +"="+gAcptNo);

        dts_AcptProcs.insertRow();
        dts_AcptProcs.setCellData(1, "ACPT_NO", scwin.gAcptNo);
        dts_AcptProcs.setCellData(1, "TRNSM_TP_CD", vTrnsmtp);
        dts_AcptProcs.setCellData(1, "EMP_NO", scwin.gEmpNo);
        dts_AcptProcs.setCellData(1, "DISCLS_PROCS_STAT_CD", scwin.gDisclsStatCd);
        // dts_AcptProcs.NameValue(1,"ACPT_APPL_TP_CD") = gAcptApplTpCd;
        dts_AcptProcs.setCellData(1, "LIST_PROCS_LOG_YN", scwin.gListProcsLogYn);
        dts_AcptProcs.setCellData(1, "DISCLS_ACPT_TP_CD", scwin.gDisclsAcptTpCd);
        dts_AcptProcs.setCellData(1, "DISCLS_DUTY_TP_CD", js_duty_tp_cd);
        if (dts_AcptProcs.getCellData(1, "ACPT_NO") === '') {
            await $c.win.alert("접수정보를 다시 읽어와야 하므로 공시뷰어를 닫으신후 다시 열어 주세요.");
            return false;
        }

        // alert('[dts_AcptProcs]'+dts_AcptProcs.Text);
        // alert('/vBzProcsNo/'+vBzProcsNo+'/gAcptNo/'+gAcptNo+'/vMainFormCd/'+vMainFormCd);

        if (await scwin.checkProcsSate(scwin.gAcptNo) === false) {
            scwin.closeParentReload();
            return false;
        } else {
            trs_AcptProcs.KeyName = "toinb_dataid4";
            // [전환검토] trs_AcptProcs.Parameters → 동적 파라미터(필요 시 sbmOptions 에 반영)
            // const sbmParams = {
            //     BZ_PROCS_NO : vBzProcsNo,
            //     ACPT_NO : scwin.gAcptNo,
            //     FORM_CD : scwin.vMainFormCd,
            //     ISUR_CD : scwin.vIsurCd,
            //     LIST_BZ_TP_CD : scwin.vListBzTpCd,
            //     LD_MKT_TP_CD : scwin.vMktTpCd
            // };
            const sbmOptions = {
                id : "sbm_trs_AcptProcs",
                action : "/DisclosureStudy.do",
                ref : "dts_AcptProcs",
                target : "trs_AcptProcs=body.content",
                isProcessMsg : false
            };

            const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
            // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
        }
    }
};

/**
 * @method
 * @name getProcsSate
 * @description 처리상태 조회하기
 * @param {*} gAcptNo gAcptNo
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.getProcsSate = async function(gAcptNo) {
    const sbmOptions = {
        id : "sbm_dts_procs_stat",
        action : "/Viewer.do",
        ref : "",
        target : "dts_procs_stat=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    scwin.vPROCS_STAT_CD = dts_procs_stat.getCellData(1, "PROCS_STAT_CD");
    scwin.vPROCS_STAT_NM = dts_procs_stat.getCellData(1, "PROCS_STAT_NM");
    scwin.vPROCS_DDTM = dts_procs_stat.getCellData(1, "PROCS_DDTM");
    scwin.vBLOCK_YN = dts_procs_stat.getCellData(1, "BLOCK_YN");
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name showProcButton
 * @description 처리버튼 생성여부
 * @param {String} pDutyProcYn pDutyProcYn
 * @param {String} pGrnlProcYn pGrnlProcYn
 * @param {String} pCloseYn pCloseYn
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.showProcButton = async function(pDutyProcYn, pGrnlProcYn, pCloseYn) {
    // alert(gDutyYn+","+pDutyProcYn+","+pGrnlProcYn+","+pCloseYn);
    await scwin.getProcsSate(scwin.gAcptNo);
    if (scwin.gAcptNo !== '') {
        // 가져온접수번호가 있으면 처리함.
        if (scwin.gApprovYn === 'Y') {
            // 처리절차가 있을 경우

            panel_1.hide();
            if ((scwin.gDutyYn === 'Y' || scwin.gDutyChrg === 'Y') && pDutyProcYn === 'Y') {
                panel_2.show("");
                if (scwin.gProcsStatCd === '00') {
                    // 미처리
                    img_approval.setBackgroundImage("../img/btn_approval_d.gif");
                    img_approval.setDisabled(true);
                } else if (scwin.gProcsStatCd === '10') {
                    // 접수
                    img_acpt.setBackgroundImage("../img/btn_Acpt_d.gif");
                    img_acpt.setDisabled(true);
                } else {
                    img_acpt.setBackgroundImage("../img/btn_Acpt_d.gif");
                    img_acpt.setDisabled(true);
                    img_approval.setBackgroundImage("../img/btn_approval_d.gif");
                    img_approval.setDisabled(true);
                    img_res.setBackgroundImage("../img/btn_reserve_d.gif");
                    img_res.setDisabled(true);
                }
            } else {
                // 팀장 및 부서장 권한일때만 보임, 팀장  : 09,   부서장: 40, 팀원: 03
                if (scwin.gJobTitle === '09' || scwin.gJobTitle === '40') {
                    // 팀장 및 부서장은 모두 부서의 문서를 처리가능하다.
                    panel_2.show("");
                    if (scwin.gProcsStatCd === '00') {
                        // 미처리
                        img_approval.setBackgroundImage("../img/btn_approval_d.gif");
                        img_approval.setDisabled(true);
                    } else if (scwin.gProcsStatCd === '10') {
                        // 검토
                        img_acpt.setBackgroundImage("../img/btn_Acpt_d.gif");
                        img_acpt.setDisabled(true);
                    } else {
                        img_acpt.setBackgroundImage("../img/btn_Acpt_d.gif");
                        img_acpt.setDisabled(true);
                        img_approval.setBackgroundImage("../img/btn_approval_d.gif");
                        img_approval.setDisabled(true);
                        img_res.setBackgroundImage("../img/btn_reserve_d.gif");
                        img_res.setDisabled(true);
                    }
                } else {
                    // 일반사용자이면서 접수문서가 소속부서에 해당할 경우
                    if (pGrnlProcYn === 'Y') {
                        panel_2.show("");
                        if (scwin.gProcsStatCd === '00') {
                            // 미처리
                            img_approval.setBackgroundImage("../img/btn_approval_d.gif");
                            img_approval.setDisabled(true);
                        } else if (scwin.gProcsStatCd === '10') {
                            // 검토
                            img_acpt.setBackgroundImage("../img/btn_Acpt_d.gif");
                            img_acpt.setDisabled(true);
                            // 유가 - 일반사용자(팀원)도 승인권한을 준다. 2020.09.04
                            // img_approval.src = "../img/btn_approval_d.gif";
                            // img_approval.disabled = true;

                        } else {
                            img_acpt.setBackgroundImage("../img/btn_Acpt_d.gif");
                            img_acpt.setDisabled(true);
                            img_approval.setBackgroundImage("../img/btn_approval_d.gif");
                            img_approval.setDisabled(true);
                            img_res.setBackgroundImage("../img/btn_reserve_d.gif");
                            img_res.setDisabled(true);
                        }
                    } else {
                        panel_2.hide();
                    }
                }
            }
        } else {
            panel_2.hide();

            // 로그한 사용자가 당번이면서 접수문서가 당번그룹에 해당할 경우
            if ((scwin.gDutyYn === 'Y' || scwin.gDutyChrg === 'Y') && pDutyProcYn === 'Y') {
                panel_1.show("");
            } else {
                // 팀장 및 부서장 권한일때만 보임, 팀장  : 09,   부서장: 40, 팀원: 03
                if (scwin.gJobTitle === '09' || scwin.gJobTitle === '40') {
                    // 팀장 및 부서장은 모두 부서의 문서를 처리가능하다.
                    panel_1.show("");
                } else {
                    // 일반사용자이면서 접수문서가 소속부서에 해당할 경우
                    if (pGrnlProcYn === 'Y') {
                        panel_1.show("");
                    } else {
                        panel_1.hide();
                        if (js_belngdepcd === '3300' || js_belngdepcd === '3E00') {
                            if (scwin.vMainFormCd === '72088' || scwin.vMainFormCd === '72089' || scwin.vMainFormCd === '72090') {
                                panel_1.show("");
                            }
                        }
                    }
                }
            }
        }
    }
};

/**
 * @method
 * @name checkProcsSate
 * @description 처리상태 조회하기
 * @param {*} gAcptNo gAcptNo
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkProcsSate = async function(gAcptNo) {
    await scwin.getProcsSate(scwin.gAcptNo);
    if (scwin.vBLOCK_YN === 'Y') {
        await $c.win.alert("(경고) 동사 주권의 매매거래가 정지되지 않았음을 알려드립니다. 거래시간 중 '매매거래정지 안내' 및 '관련공시' 배포는 매매거래가 정지된 이후 처리되어야 합니다. 거래정지 여부를 확인하신 후에 처리하시기 바랍니다.");
        return false;
    }
    if (scwin.gProcsStatCd !== scwin.vPROCS_STAT_CD) {
        await $c.win.alert("본 공시가 " + scwin.vPROCS_DDTM + "에  이미 [" + scwin.vPROCS_STAT_NM + "] 처리가 되었습니다.");
        // fn_CloseParentReload();
        return false;
    } else {
        return true;
    }
};

/**
 * @method
 * @name checkProcsSateKOSDAQ
 * @description 처리상태 조회하기
 * @param {*} gAcptNo gAcptNo
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkProcsSateKOSDAQ = async function(gAcptNo) {
    await scwin.getProcsSate(scwin.gAcptNo);
    if (scwin.vBLOCK_YN === 'Y') {
        await $c.win.alert(scwin.gTrdHaltMsg);
        return false;
    }
    if (scwin.vPROCS_STAT_CD !== '00') {
        await $c.win.alert("본 공시가 " + scwin.vPROCS_DDTM + "에  이미 [" + scwin.vPROCS_STAT_NM + "] 처리가 되었습니다.");
        // fn_CloseParentReload();
        return false;
    } else {
        return true;
    }
};

/**
