scwin.spacYN = function() {
    let url = "/listingCommon.do?method=listGeneral" + "&outputMessageId=LISTING_SPAC_YN" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstproc.lstrcv.select.isuinst.spac.condition" + "&{P}param01=" + scwin.vIsurCd + // 회사코드
