/**
 * @method
 * @name moveBizProcPage
 * @description move Biz Proc Page 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.moveBizProcPage = async function() {
    let url = "&" + scwin.vIsurCd;
    url += "&" + scwin.gAcptNo;
    url += "&" + scwin.vSecuGrpId;
    url += "&" + scwin.vMktTpCd;
    url += "&" + scwin.vComAbbrv;
    if ($c.frame.path("/top") !== undefined) {
        $c.frame.path("/top").WinOpen("STF05200", scwin.vUrl + "?" + frame.FrameID + url, scwin.vWinTitle, 1275, 785);
    } else {
        await $c.frame.CreateFrame("STF05200", scwin.vUrl, scwin.vWinTitle, 10, 10, 1275, 785, "window", 0, 0, true);
    }
};

/**
 * @method
 * @name closeParentReload
 * @description 뷰어 닫고,  검색목록 reload
 * @returns {void}
 * @hidden N
 */
scwin.closeParentReload = function() {
    // 화면닫기
    $c.frame.path("../").fn_CloseWin();
    $c.frame.path("../").fn_PvdSearch();
};

/**
 * @method
 * @name getParentProvider
 * @description get Parent Provider 처리
 * @returns {void}
 * @hidden N
 */
scwin.getParentProvider = function() {
    let url = $c.frame.path("../").srcUrl;
    const arr = url.split("?");
    // alert(url +"     =      "+ arr);
    return (arr.length >= 1 ? $c.frame.path("../../" + arr[1]) : undefined);
};

/**
