    let url = "/lstproc/ULDSTF05014.gfm?ISUR_CD=" + scwin.vIsurCd + "&ACPT_NO=" + scwin.gAcptNo + "&FORM_CD=" + scwin.vMainFormCd;

    // 최초, 정정
    if (scwin.gDisclsAcptTpCd === 'M' || scwin.gDisclsAcptTpCd === 'F') {
        // 70932 :신주상장신청서,  70933 : 변경상장신청서, 70934:신주상장신청서(DR)
        if (scwin.vMainFormCd === '70932' || scwin.vMainFormCd === '70934' || scwin.vMainFormCd === '70933' || scwin.vMainFormCd === '33032' || scwin.vMainFormCd === '33033') {
            await $c.frame.CreateDialogFrame("COS_LISTFEE", url, "상장수수료발송", 300, -500, 410, 200, "window");
